WITH cleaned AS (SELECT *, LENGTH(event_type) AS event_type_length FROM web_events WHERE event_time > TO_DATE('2023-07-23') AND session_id IN (3, 30)) SELECT p.browser, p.country, src.event_type, COUNT(*) AS cnt, MAX(src.event_type_length) AS max_event_type_length, MAX(src.duration_sec) AS max_duration_sec FROM cleaned src INNER JOIN sessions p ON src.session_id = p.id GROUP BY p.browser, p.country, src.event_type ORDER BY cnt DESC NULLS LAST;
